// ***************
// Filename: edge_event_capture_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of edge_event_capture: its AXI4-Lite register
//   slave (axi4_lite_slave front end) with every register of the block, the
//   ID block first; the registers go to edge_event_capture's logic on named
//   ports, its status comes back on input ports. Edge event capture: enables,
//   debounce, pending edges, counters, timestamp, interrupt enables.
//   Generated by ip/scripts/regmap_gen.py from edge_event_capture_regs.json:
//   edit the JSON and regenerate (the IP_VERSION / IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "EDGE" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 CTRL        RW   [0] capture enabled, reset 0x1
//     0x14 RISE_EN     RW   rising edges captured per input, reset 0x0
//     0x18 FALL_EN     RW   falling edges captured per input, reset 0x0
//     0x1C DEBOUNCE    RW   clocks an input must be stable before its edge
//                       counts (0: none), reset 0x0
//     0x20 RISE_PEND   W1C  rising edges seen per input; write 1 to clear,
//                       reset 0x0
//     0x24 FALL_PEND   W1C  falling edges seen per input; write 1 to clear,
//                       reset 0x0
//     0x28 EVENT_COUNT RO   clocks with at least one captured edge
//     0x2C TIMESTAMP   RO   free-running timestamp (TS_W bits)
//     0x30 DROP_COUNT  RO   event records lost (FIFO full)
//     0x34 IRQ_EN      RW   irq_o while a pending edge of an enabled input is
//                       set, reset 0x0
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - aclk.
//   Reset - synchronous active low aresetn. Latency - 2 clocks per write and
//   read.
// Date: 2026-10-12
module edge_event_capture_regs #(
  parameter int WIDTH = 8  // inputs (1..32)
) (
  input  logic             aclk,            // clock
  input  logic             aresetn,         // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  input  logic [7:0]       s_axil_awaddr,   // AXI4-Lite
  input  logic             s_axil_awvalid,
  output logic             s_axil_awready,
  input  logic [31:0]      s_axil_wdata,
  input  logic [3:0]       s_axil_wstrb,
  input  logic             s_axil_wvalid,
  output logic             s_axil_wready,
  output logic [1:0]       s_axil_bresp,
  output logic             s_axil_bvalid,
  input  logic             s_axil_bready,
  input  logic [7:0]       s_axil_araddr,
  input  logic             s_axil_arvalid,
  output logic             s_axil_arready,
  output logic [31:0]      s_axil_rdata,
  output logic [1:0]       s_axil_rresp,
  output logic             s_axil_rvalid,
  input  logic             s_axil_rready,
  output logic             ctrl_o,          // CTRL (RW): register value
  output logic             ctrl_wr_o,       // CTRL: one-clock pulse at every software write
  output logic [WIDTH-1:0] rise_en_o,       // RISE_EN (RW): register value
  output logic             rise_en_wr_o,    // RISE_EN: one-clock pulse at every software write
  output logic [WIDTH-1:0] fall_en_o,       // FALL_EN (RW): register value
  output logic             fall_en_wr_o,    // FALL_EN: one-clock pulse at every software write
  output logic [16-1:0]    debounce_o,      // DEBOUNCE (RW): register value
  output logic             debounce_wr_o,   // DEBOUNCE: one-clock pulse at every software write
  output logic [WIDTH-1:0] rise_pend_o,     // RISE_PEND (W1C): status (software clears)
  output logic             rise_pend_wr_o,  // RISE_PEND: one-clock pulse at every software write
  input  logic [WIDTH-1:0] rise_pend_set_i, // RISE_PEND: hardware sets bits (one-clock pulses)
  output logic [WIDTH-1:0] fall_pend_o,     // FALL_PEND (W1C): status (software clears)
  output logic             fall_pend_wr_o,  // FALL_PEND: one-clock pulse at every software write
  input  logic [WIDTH-1:0] fall_pend_set_i, // FALL_PEND: hardware sets bits (one-clock pulses)
  input  logic [32-1:0]    event_count_i,   // EVENT_COUNT (RO): value read
  input  logic [32-1:0]    timestamp_i,     // TIMESTAMP (RO): value read
  input  logic [32-1:0]    drop_count_i,    // DROP_COUNT (RO): value read
  output logic [WIDTH-1:0] irq_en_o,        // IRQ_EN (RW): register value
  output logic             irq_en_wr_o      // IRQ_EN: one-clock pulse at every software write
);
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "EDGE";
  localparam logic [31:0] IP_VERSION = "1.10";
  localparam logic [31:0] IP_DATE    = 32'h10122026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_CTRL = 8'h10;
  localparam logic [7:0] A_RISE_EN = 8'h14;
  localparam logic [7:0] A_FALL_EN = 8'h18;
  localparam logic [7:0] A_DEBOUNCE = 8'h1C;
  localparam logic [7:0] A_RISE_PEND = 8'h20;
  localparam logic [7:0] A_FALL_PEND = 8'h24;
  localparam logic [7:0] A_EVENT_COUNT = 8'h28;
  localparam logic [7:0] A_TIMESTAMP = 8'h2C;
  localparam logic [7:0] A_DROP_COUNT = 8'h30;
  localparam logic [7:0] A_IRQ_EN = 8'h34;
  localparam int MAP_WORDS = 14;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(aclk),
    .aresetn(aresetn),
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .wr_en_o(wr_en),
    .wr_addr_o(wr_addr),
    .wr_data_o(wr_data),
    .wr_strb_o(wr_strb),
    .wr_err_i(wr_err_q),
    .rd_en_o(rd_en),
    .rd_addr_o(rd_addr),
    .rd_data_i(rd_data),
    .rd_valid_i(1'b1),
    .rd_err_i(1'b0)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] ctrl_q;
  logic [31:0] rise_en_q;
  logic [31:0] fall_en_q;
  logic [31:0] debounce_q;
  logic [31:0] rise_pend_q;
  logic [31:0] fall_pend_q;
  logic [31:0] irq_en_q;
  always_ff @(posedge aclk) begin
    if (!aresetn) begin
      ctrl_q <= 32'h1;
      ctrl_wr_o <= 1'b0;
      rise_en_q <= 32'h0;
      rise_en_wr_o <= 1'b0;
      fall_en_q <= 32'h0;
      fall_en_wr_o <= 1'b0;
      debounce_q <= 32'h0;
      debounce_wr_o <= 1'b0;
      rise_pend_q <= 32'h0;
      rise_pend_wr_o <= 1'b0;
      fall_pend_q <= 32'h0;
      fall_pend_wr_o <= 1'b0;
      irq_en_q <= 32'h0;
      irq_en_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_EVENT_COUNT || wa == A_TIMESTAMP || wa == A_DROP_COUNT);   // writes to read-only words: SLVERR
      begin
        ctrl_wr_o <= wr_en && wa == A_CTRL;
        if (wr_en && wa == A_CTRL) ctrl_q <= (ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        rise_en_wr_o <= wr_en && wa == A_RISE_EN;
        if (wr_en && wa == A_RISE_EN) rise_en_q <= (rise_en_q & ~wmask) | (wr_data & wmask);
      end
      begin
        fall_en_wr_o <= wr_en && wa == A_FALL_EN;
        if (wr_en && wa == A_FALL_EN) fall_en_q <= (fall_en_q & ~wmask) | (wr_data & wmask);
      end
      begin
        debounce_wr_o <= wr_en && wa == A_DEBOUNCE;
        if (wr_en && wa == A_DEBOUNCE) debounce_q <= (debounce_q & ~wmask) | (wr_data & wmask);
      end
      begin
        rise_pend_wr_o <= wr_en && wa == A_RISE_PEND;
        rise_pend_q <= ((wr_en && wa == A_RISE_PEND) ? rise_pend_q & ~(wr_data & wmask) : rise_pend_q) | 32'(rise_pend_set_i);   // a set wins over a clear
      end
      begin
        fall_pend_wr_o <= wr_en && wa == A_FALL_PEND;
        fall_pend_q <= ((wr_en && wa == A_FALL_PEND) ? fall_pend_q & ~(wr_data & wmask) : fall_pend_q) | 32'(fall_pend_set_i);   // a set wins over a clear
      end
      begin
        irq_en_wr_o <= wr_en && wa == A_IRQ_EN;
        if (wr_en && wa == A_IRQ_EN) irq_en_q <= (irq_en_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign ctrl_o = ctrl_q[1-1:0];
  assign rise_en_o = rise_en_q[WIDTH-1:0];
  assign fall_en_o = fall_en_q[WIDTH-1:0];
  assign debounce_o = debounce_q[16-1:0];
  assign rise_pend_o = rise_pend_q[WIDTH-1:0];
  assign fall_pend_o = fall_pend_q[WIDTH-1:0];
  assign irq_en_o = irq_en_q[WIDTH-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge aclk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_CTRL: rd_data = ctrl_q;
      A_RISE_EN: rd_data = rise_en_q;
      A_FALL_EN: rd_data = fall_en_q;
      A_DEBOUNCE: rd_data = debounce_q;
      A_RISE_PEND: rd_data = rise_pend_q;
      A_FALL_PEND: rd_data = fall_pend_q;
      A_EVENT_COUNT: rd_data = 32'(event_count_i);
      A_TIMESTAMP: rd_data = 32'(timestamp_i);
      A_DROP_COUNT: rd_data = 32'(drop_count_i);
      A_IRQ_EN: rd_data = irq_en_q;
      default: begin
      end
    endcase
  end
endmodule
